67:         {
68:             if (form == null)
69:                 return;
70: 
71:             string formName = form.GetType().Name;
72: 
73:             try
74:             {
75:                 LocalizationCache.Instance.Initialize(formName);
76:                 (form as ILanguage)?.GetUI();
77: 
78:                 if (!LocalizationManager.HasFormTranslation(formName))
