97:         private static void LocalizeFormByTranslationKeys(Control form, string formName)
98:         {
99:             var formTranslations = LocalizationCache.Instance._formCache.ContainsKey(formName)
100:                 ? LocalizationCache.Instance._formCache[formName]
101:                 : null;
102: 
103:             if (formTranslations == null)
104:                 return;
105: 
106:             foreach (var kvp in formTranslations)
107:             {
108:                 string controlKey = kvp.Key;
109:                 JToken translationValue = kvp.Value;
110: 
111:                 if (translationValue is JObject translationObj)
112:                 {
113:                     object component = FindComponentByKey(form, controlKey);
114:                     if (component != null)
115:                     {
116:                         ApplyTranslationToComponent(component, translationObj, controlKey);
117:                     }
118:                 }
119:             }

230:         private static void ApplyTranslationToComponent(object component, JObject translationObj, string componentKey)
231:         {
232:             try
233:             {
234:                 string currentLanguage = LanguageSettings.GetInstance().Language.ToString();
235: 
236:                 // 优先应用 JSON 中指定的 "Property"
237:                 string targetProperty = translationObj["Property"]?.ToString() ?? GetDefaultProperty(component.GetType());
238: 
239:                 if (translationObj[currentLanguage] is JValue valueToken)
240:                 {
241:                     string translatedText = valueToken.Value<string>();
242:                     if (!string.IsNullOrEmpty(translatedText))
243:                     {
244:                         SetComponentProperty(component, targetProperty, translatedText);
245:                         // System.Diagnostics.Debug.WriteLine($"本地化组件: {component.GetType().Name}.{componentKey} -> {targetProperty} = '{translatedText}'");
246:                     }
247:                 }
248: 
249:                 // 应用ToolTipText (适用于 BarItem 等)
250:                 var toolTipProperty = component.GetType().GetProperty("Hint"); // DevExpress Hint 属性
251:                 if (translationObj["ToolTipText"] is JObject toolTipObj && toolTipProperty != null)
252:                 {
253:                     string toolTipText = GetTranslationValue(toolTipObj, currentLanguage);
254:                     if (!string.IsNullOrEmpty(toolTipText))
255:                     {
256:                         SetComponentProperty(component, "Hint", toolTipText);
257:                     }
258:                 }
259: 
260:                 // 应用其他属性
261:                 if (translationObj["Properties"] is JToken propertiesToken)
262:                 {
263:                     ApplyAdditionalProperties(component, propertiesToken, currentLanguage);
264:                 }
265:             }
266:             catch (Exception ex)
267:             {
268:                 System.Diagnostics.Debug.WriteLine($"应用翻译失败: {componentKey}, 错误: {ex.Message}");
269:             }

