338:         private static void SetComponentProperty(object component, string propertyName, object value)
339:         {
340:             if (component == null) return;
341:             try
342:             {
343:                 PropertyInfo property = component.GetType().GetProperty(propertyName, BindingFlags.Public | BindingFlags.Instance);
344:                 if (property != null && property.CanWrite)
345:                 {
346:                     object convertedValue = ConvertValue(value, property.PropertyType);
347:                     property.SetValue(component, convertedValue);
348:                 }
349:                 else
350:                 {
351:                     System.Diagnostics.Debug.WriteLine($"属性未找到或不可写: {component.GetType().Name}.{propertyName}");
352:                 }
353:             }
354:             catch (Exception ex)
355:             {
356:                 string componentName = component.GetType().GetProperty("Name")?.GetValue(component)?.ToString() ?? "Unknown";
357:                 System.Diagnostics.Debug.WriteLine($"设置组件属性失败: {componentName}.{propertyName} = {value}, 错误: {ex.Message}");
358:             }
